package main

import "testing"

func TestLooksAIGenerated(t *testing.T) {
	hidden := []string{
		"A.I Generated Picture #aigenerated #midjourney #wallpaper",
		"A stunning AI-generated luxury beauty portrait",
		"ai art of a cat",
		"AI Art",
		"made with Midjourney v6",
		"Created using Stable Diffusion",
		"stablediffusion prompt",
		"generated by AI",
		"#aiart",
		"#AIartwork #cute",
		"#ai_art",
		"#generativeai",
		"Cute girl, DALL-E 3 render",
		"novelai gallery",
	}
	shown := []string{
		"",
		"Ryomen Sukuna phone wallpaper",
		"Save it for your pink aesthetic collection! #AnyaForger #SpyXFamily",
		"#airplane #aircraft #airjordan",
		"Kitchen paint, 3 coats of Dalle verde", // "dalle" without a version number
		"ai que saudade",                        // Portuguese interjection
		"Naruto fan art, hand drawn",
		"Tail and sail boat",
		"aisle seat",
		"#aime",
	}

	for _, text := range hidden {
		if !looksAIGenerated(text) {
			t.Errorf("expected %q to look AI-generated", text)
		}
	}
	for _, text := range shown {
		if looksAIGenerated(text) {
			t.Errorf("expected %q not to look AI-generated", text)
		}
	}
}
